otherwise.set-body:
{
  "status": "error",
  "severity": "recoverable",
  "category": "network",
  "backendStatus": null,
  "code": "no_response_from_backend",
  "message": "No response received from upstream backend after retries.",
  "correlationId": "@(context.Variables["correlationId"])",
  "details": {}
}

on-error.set-body:
{
  "status": "error",
  "severity": "non-recoverable",
  "category": "gateway",
  "backendStatus": null,
  "code": "policy_execution_error",
  "message": "An error occurred processing the request in API Management.",
  "correlationId": "@(context.Variables[\"responseCorrelationId\"])",
  "details": {
    "lastError": "@(context.Variables[\"responseLastError\"])"
  }
}
